def e_k(k, xvals):
    if k==0: return Q(1)
    s=Q(0)
    for c in combinations(range(len(xvals)),k):
        t=Q(1)
        for i in c: t*=xvals[i]
        s+=t
    return s

def Dval(Dspec, xvals):
    v=Q(1)
    for k,p in Dspec.items():
